// DOMParser and XMLSerializer (ZN-706): a bitmap font (BMFont XML, as PixiJS's and Phaser's loaders read it) and an SVG (as Phaser's SVG
// loader reads it) parse to the nodes a browser gives. The same file runs in headless Chrome (tests/golden/webenv/domparser.out was written
// from its DOMParser through tools/cdp.py) and on the web environment.
const font = `<?xml version="1.0"?>
<!-- generated by a bitmap font tool -->
<font>
  <info face="Arial Black" size="32" bold="1" italic="0" charset="" unicode="1" stretchH="100" smooth="1" aa="1" padding="0,0,0,0" spacing="1,1"/>
  <common lineHeight="45" base="35" scaleW="256" scaleH="256" pages="1" packed="0"/>
  <pages>
    <page id="0" file="font_0.png"/>
  </pages>
  <chars count="3">
    <char id="65" x="0" y="0" width="28" height="30" xoffset="0" yoffset="5" xadvance="27" page="0" chnl="15"/>
    <char id="66" x="29" y="0" width="22" height="30" xoffset="2" yoffset="5" xadvance="24" page="0" chnl="15"/>
    <char id="32" x="0" y="0" width="0" height="0" xoffset="0" yoffset="0" xadvance="9" page="0" chnl="15"/>
  </chars>
  <kernings count="1">
    <kerning first="65" second="66" amount="-1"/>
  </kernings>
</font>`;
const svg = `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="64" height="32" viewBox="0 0 64 32">
  <defs><linearGradient id="g1"><stop offset="0" stop-color="#f00"/><stop offset="1" stop-color="#00f"/></linearGradient></defs>
  <g id="layer" class="shapes main" transform="translate(2 2)">
    <rect id="box" x="0" y="0" width="20" height="20" fill="url(#g1)"/>
    <circle cx="40" cy="10" r="8" fill="#0a0"/>
    <use xlink:href="#box" x="30"/>
  </g>
  <text x="1" y="30">A &amp; B &lt;&#x41;&gt;<![CDATA[ raw <cdata> ]]></text>
</svg>`;

const lines = [];
const out = (...a) => lines.push(a.join(' '));
function dump(n, depth) {
  const pad = '  '.repeat(depth);
  if (n.nodeType === 1) {
    const attrs = [];
    for (let i = 0; i < n.attributes.length; i++) { const a = n.attributes[i]; attrs.push(`${a.name}=${JSON.stringify(a.value)}${a.namespaceURI ? '{' + a.namespaceURI + '}' : ''}`); }
    out(pad + `element ${n.nodeName} local=${n.localName} prefix=${n.prefix} ns=${n.namespaceURI} children=${n.childNodes.length} elements=${n.childElementCount}`, attrs.join(' '));
    for (let c = n.firstChild; c; c = c.nextSibling) dump(c, depth + 1);
  } else out(pad + `${n.nodeType} ${n.nodeName} ${JSON.stringify(n.nodeValue)}`);
}

const parser = new DOMParser();
const f = parser.parseFromString(font, 'text/xml');
out('font: document', f.nodeType, f.nodeName, f.documentElement.nodeName, f.childNodes.length, 'parsererror', f.getElementsByTagName('parsererror').length);
for (let c = f.firstChild; c; c = c.nextSibling) dump(c, 0);
// what the bitmap font loaders read
const info = f.getElementsByTagName('info')[0], common = f.getElementsByTagName('common')[0];
out('font: face', info.getAttribute('face'), 'size', parseInt(info.getAttribute('size'), 10), 'lineHeight', common.getAttribute('lineHeight'), 'missing', info.getAttribute('nope'), info.hasAttribute('bold'));
const chars = f.getElementsByTagName('char');
out('font: chars', chars.length, [...Array(chars.length).keys()].map(i => chars[i].getAttribute('id') + ':' + chars[i].getAttribute('xadvance')).join(','));
out('font: page', f.getElementsByTagName('page')[0].getAttribute('file'), 'kerning', f.getElementsByTagName('kerning')[0].getAttribute('amount'));
out('font: selectors', f.querySelector('chars > char[id="66"]').getAttribute('x'), f.querySelectorAll('char').length, f.documentElement.firstElementChild.nodeName,
  f.documentElement.lastElementChild.nodeName, info.nextElementSibling.nodeName, common.previousElementSibling.nodeName, f.documentElement.children.length);

const s = parser.parseFromString(svg, 'image/svg+xml');
out('svg: document', s.nodeType, s.documentElement.nodeName, s.documentElement.namespaceURI, 'parsererror', s.getElementsByTagName('parsererror').length);
dump(s.documentElement, 0);
const root = s.getElementsByTagName('svg')[0];
out('svg: size', root.getAttribute('width'), root.getAttribute('height'), root.hasAttribute('viewBox'), root.getAttribute('viewBox').split(/\s+|,/).join('|'));
const use = s.getElementsByTagName('use')[0];
out('svg: use', use.getAttributeNS('http://www.w3.org/1999/xlink', 'href'), use.getAttribute('xlink:href'));
out('svg: ns lookup', s.getElementsByTagNameNS('http://www.w3.org/2000/svg', 'stop').length, s.getElementsByTagName('stop')[1].getAttribute('stop-color'));
out('svg: by id', s.getElementById('box').getAttribute('width'), s.querySelector('#layer').getAttribute('transform'), s.querySelector('.main circle').getAttribute('r'),
  s.querySelectorAll('g > *').length, s.querySelector('rect').closest('g').getAttribute('id'), s.querySelector('circle').matches('g circle'));
out('svg: text', JSON.stringify(s.getElementsByTagName('text')[0].textContent));
// what Phaser's SVG loader does before it draws: set the size, then serialise
root.setAttribute('width', '128px');
const text = new XMLSerializer().serializeToString(s.getElementsByTagName('circle')[0]);
const back = parser.parseFromString(text, 'image/svg+xml').documentElement, backAttrs = [];   // the order of xmlns among the attributes differs (xmldom writes it last)
for (let i = 0; i < back.attributes.length; i++) backAttrs.push(back.attributes[i].name + '=' + back.attributes[i].value);
out('svg: serialised circle', back.nodeName, back.namespaceURI, backAttrs.sort().join(' '));
out('svg: serialised root starts', new XMLSerializer().serializeToString(root).slice(0, 110));

// a document that is not well formed: a parsererror element, no exception
const bad = parser.parseFromString('<font><info></font>', 'text/xml');
out('bad: parsererror', bad.getElementsByTagName('parsererror').length > 0);
let thrown = 'none';
try { parser.parseFromString('<a/>', 'text/plain'); } catch (e) { thrown = e.name; }
out('bad: type', thrown);
console.log(lines.join('\n'));
